function RunBytes([long]$Vcn,[long]$Next,[long]$Lcn){$bytes=New-Object byte[] 32;[BitConverter]::GetBytes([uint32]1).CopyTo($bytes,0);[BitConverter]::GetBytes($Vcn).CopyTo($bytes,8);[BitConverter]::GetBytes($Next).CopyTo($bytes,16);[BitConverter]::GetBytes($Lcn).CopyTo($bytes,24);return ,$bytes}
