$other=[Ntfs2Refs.NativeAllocationWorkload]::Extents((RunBytes 0 1 100),4096);$bitmap[28]=$bitmap[28]-bor16;[Ntfs2Refs.NativeAllocationWorkload]::CheckAllocated($bitmap,$other,2097152,$false);$checks++
$bad=[byte[]]$bitmap.Clone();$bad[0]=1;Reject {[Ntfs2Refs.NativeAllocationWorkload]::CheckAllocated($bad,$runs,2097152,$true)} 'Partial/rounded bitmap accepted as whole volume.'
